{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 도시공원 조례상 금지행위 안내판 설치 의무 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 도시공원 조례 제22조의2 제1항에 따르면 시장은 법 제49조제1항 및 제2항에 따라 금지행위가 적용되는 도시공원 입구에 안내표지를 설치하여야 합니다. 따라서 금지행위를 이용자가 알 수 있도록 안내판을 설치하게 되어 있습니다.",
          "b_ids": "도시공원:제22조의2제1항"
        }
      ],
      "e_status": "ANSWERED"
    },
    {
      "a_request": "R2",
      "b_asked": "안내판 설치 위치가 공원 안 아무 곳이면 되는지 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "같은 조항에서 안내표지는 도시공원 '입구'에 설치하여야 한다고 정하고 있으므로, 공원 안 아무 곳이 아니라 입구에 설치해야 합니다.",
          "b_ids": "도시공원:제22조의2제1항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
